  '# Production Readiness Audit',
  '## Executive Summary',
  '## Critical Findings',
  '## High Priority Findings',
  '## Medium Priority Findings',
  '## Low Priority Findings',
  '## Cross-Cutting Design / Brand Issues',
  '## Cross-Cutting Technical Issues',
  '## Production Dependencies',
  '## Master Remediation Roadmap',
  '### Phase 1 — Client / Production Blockers',
  '### Phase 2 — Brand & Visual Corrections',
  '### Phase 3 — UX & Functional Improvements',
  '### Phase 4 — Technical Hardening & Cleanup',
  '### Phase 5 — Final Production Polish',
  '## Recommended Execution Order',
  '## Final Production Acceptance Checklist',
];
const missingHeadings = requiredHeadings.filter((heading) => !report.includes(heading));
const sectionSlice = (startHeading, endHeading) => {
  const start = report.indexOf(startHeading);
  if (start === -1) return '';
  const end = endHeading ? report.indexOf(endHeading) : report.length;
  return report.slice(start, end === -1 ? report.length : end);
};
const findingFields = [
  'Severity:', 'Location:', 'Current Condition:', 'Evidence:', 'Why It Matters:',
  'Required Remediation:', 'Implementation Steps:', 'Acceptance Criteria:',
  'Verification Method:', 'Dependencies / Blockers:', 'Scope:'
];
const severitySections = [
  ['critical', '## Critical Findings', '## High Priority Findings'],
  ['high', '## High Priority Findings', '## Medium Priority Findings'],
  ['medium', '## Medium Priority Findings', '## Low Priority Findings'],
  ['low', '## Low Priority Findings', '## Cross-Cutting Design / Brand Issues'],
];
const severityCounts = {};
const remediationValidationFailures = [];
for (const [key, startHeading, endHeading] of severitySections) {
  const section = sectionSlice(startHeading, endHeading);
  const findings = section.match(/^###\s+/gm) || [];
  severityCounts[key] = findings.length;
  const findingBlocks = section.split(/^###\s+/m).slice(1);
  findingBlocks.forEach((block, index) => {
    const missing = findingFields.filter((field) => !block.includes(field));
    if (missing.length) {
      remediationValidationFailures.push(`${startHeading} finding ${index + 1} missing: ${missing.join(', ')}`);
    }
  });
}
const executiveSummary = sectionSlice('## Executive Summary', '## Critical Findings');
const primaryShipmentBlockers = [...executiveSummary.matchAll(/^-\s+(.*)$/gm)].map((match) => match[1]).slice(0, 10);
const productionDependenciesSection = sectionSlice('## Production Dependencies', '## Master Remediation Roadmap');
const validationFailures = [];
if (missingHeadings.length) validationFailures.push(...missingHeadings.map((heading) => `Missing heading: ${heading}`));
if (!/overall readiness/i.test(executiveSummary)) validationFailures.push('Executive Summary must include overall readiness.');
if (!/primary shipment blockers/i.test(executiveSummary)) validationFailures.push('Executive Summary must include primary shipment blockers.');
if (!/strongest areas/i.test(executiveSummary)) validationFailures.push('Executive Summary must include strongest areas.');
if (!/immediate action/i.test(executiveSummary)) validationFailures.push('Executive Summary must include immediate action.');
if (!/CRITICAL:\s*\d+/i.test(executiveSummary) || !/HIGH:\s*\d+/i.test(executiveSummary) || !/MEDIUM:\s*\d+/i.test(executiveSummary) || !/LOW:\s*\d+/i.test(executiveSummary)) {
  validationFailures.push('Executive Summary must include exact severity counts for CRITICAL, HIGH, MEDIUM, and LOW.');
}
if (!/PASS|FAIL|NOT CONFIGURED|NOT EXECUTED|UNKNOWN \/ ACCESS REQUIRED/.test(productionDependenciesSection)) {
  validationFailures.push('Production Dependencies section must include allowed dependency status values.');
}
validationFailures.push(...remediationValidationFailures);
const context = $('Aggregate Batch Analyses').first().json;
return {
  json: {
    ...context,
    report,
    validationResults: validationFailures,
    reportStructureValid: missingHeadings.length === 0,
    findingRemediationValidationPassed: remediationValidationFailures.length === 0,
    severityCounts,
    primaryShipmentBlockers,
  },
};

if (($json.validationResults || []).length === 0) {
  return { json: $json };
}
return [];

if (($json.validationResults || []).length > 0) {
  throw new Error(`AUDIT_REPORT.md validation failed after one repair pass: ${$json.validationResults.join(' | ')}`);
}
return [];

return {
  json: {
    ...$json,
    auditCompleted: true,
    validationSummary: {
      validationResults: $json.validationResults,
      reportStructureValid: $json.reportStructureValid,
      findingRemediationValidationPassed: $json.findingRemediationValidationPassed,
    },
  },
};

if ($json.writeReport === false) {
  return { json: $json };
}
return [];

if ($json.writeReport === true) {
  return { json: $json };
}
return [];

